import{_ as a,o as i,c as o,b3 as r}from"./chunks/framework.VnelH-cX.js";const l="/docs-imgs/guide/SnowShot_2025-10-28_02-46-22.webp",u=JSON.parse('{"title":"AI 对话","description":"","frontmatter":{},"headers":[],"relativePath":"guide/function/aiChat.md","filePath":"guide/function/aiChat.md","lastUpdated":1786700458000}'),n={name:"guide/function/aiChat.md"};function s(e,t,g,h,A,I){return i(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="ai-对话" tabindex="-1">AI 对话 <a class="header-anchor" href="#ai-对话" aria-label="Permalink to &quot;AI 对话&quot;">​</a></h1><p>Wing Shot 的 AI 对话功能通过下载<strong>AI 对话</strong>插件开启，启动后将激活 AI 对话功能，让您能快速访问最前沿的 AI 大模型，助力效率提升。</p><p><img src="'+l+'" alt="AI 对话"></p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><p>打开 Wing Shot 界面，点击侧边栏菜单<strong>个性化</strong>下的<strong>插件</strong>打开插件管理页面。接着找到<strong>AI 对话</strong>插件，点击<strong>安装</strong>按钮即可完成 AI 对话插件的安装。</p><p>安装完成后，侧边栏菜单<strong>工具栏</strong>下会自动增加<strong>AI 对话</strong>选项，点击即可进入 AI 对话页面。</p><h2 id="主要功能" tabindex="-1">主要功能 <a class="header-anchor" href="#主要功能" aria-label="Permalink to &quot;主要功能&quot;">​</a></h2><p>AI 对话功能为你提供了便捷的 AI 助手访问体验：</p><ul><li><strong>智能对话</strong>：与最前沿的 AI 大模型进行自然对话，获取各类问题的解答</li><li><strong>开箱即用</strong>：Wing Shot 默认提供了开箱可用的 AI 对话服务，无需额外配置即可使用</li><li><strong>多模型支持</strong>：支持配置多个不同的 AI 服务提供商和模型</li><li><strong>翻译增强</strong>：配合<strong>翻译</strong>插件，可以使用 AI 大模型提供更高质量的翻译结果</li></ul><h2 id="使用-ai-对话" tabindex="-1">使用 AI 对话 <a class="header-anchor" href="#使用-ai-对话" aria-label="Permalink to &quot;使用 AI 对话&quot;">​</a></h2><p>点击侧边栏<strong>工具栏</strong>下的<strong>AI 对话</strong>选项，即可进入对话界面。在输入框中输入你的问题或需求，AI 将为你提供智能回复。</p><p>通过 AI 对话功能，你可以：</p><ul><li>咨询各类专业问题</li><li>进行创作和头脑风暴</li><li>获取学习和工作建议</li><li>处理文本编辑和优化任务</li><li>以及更多 AI 能够帮助你的场景</li></ul><h2 id="快捷功能" tabindex="-1">快捷功能 <a class="header-anchor" href="#快捷功能" aria-label="Permalink to &quot;快捷功能&quot;">​</a></h2><p>Wing Shot 提供了快速唤起 AI 对话的全局快捷键，让您在任何场景下都能快速访问 AI 助手。</p><h3 id="配置快捷键" tabindex="-1">配置快捷键 <a class="header-anchor" href="#配置快捷键" aria-label="Permalink to &quot;配置快捷键&quot;">​</a></h3><ol><li>在侧边栏点击<strong>快捷功能</strong>菜单</li><li>找到<strong>AI 对话</strong>相关的快捷功能</li><li>点击右侧的按键配置按钮</li><li>录入所需快捷键后确认即可</li></ol><h3 id="快捷唤起场景" tabindex="-1">快捷唤起场景 <a class="header-anchor" href="#快捷唤起场景" aria-label="Permalink to &quot;快捷唤起场景&quot;">​</a></h3><p>配置快捷键后，您可以在以下场景快速唤起 AI 对话：</p><ul><li><strong>日常工作</strong>：在编辑文档、浏览网页等任何场景下，按下快捷键即可快速咨询 AI</li><li><strong>快速翻译</strong>：选中文本后唤起 AI，快速进行翻译或润色</li><li><strong>灵感记录</strong>：随时随地记录想法，让 AI 帮助整理思路</li></ul><h2 id="自定义-ai-对话-api" tabindex="-1">自定义 AI 对话 API <a class="header-anchor" href="#自定义-ai-对话-api" aria-label="Permalink to &quot;自定义 AI 对话 API&quot;">​</a></h2><p>如果你想使用自己的 AI API 密钥或其他 AI 服务提供商，可以按照以下步骤配置：</p><ol><li>在侧边栏点击<strong>设置</strong>下的<strong>功能设置</strong></li><li>找到<strong>AI 对话</strong>设置选项</li><li>点击添加按钮，输入你的 API 配置信息： <ul><li>API 地址</li><li>API 密钥</li><li>模型名称等相关参数</li></ul></li><li>输入完后即可在 AI 对话相关功能中访问配置的大模型服务</li></ol><h2 id="与翻译功能配合" tabindex="-1">与翻译功能配合 <a class="header-anchor" href="#与翻译功能配合" aria-label="Permalink to &quot;与翻译功能配合&quot;">​</a></h2><p>如果你同时安装了<strong>翻译</strong>插件，AI 对话功能将为翻译提供强大的支持：</p><ul><li>使用 AI 大模型进行翻译，获得更准确、更符合上下文的翻译结果</li><li>在<strong>功能设置</strong>的<strong>翻译</strong>选项中，修改<strong>翻译服务</strong>选择 AI 模型作为翻译引擎</li><li>自定义的 AI API 也可以用于翻译服务，只需在<strong>AI 对话</strong>设置中配置相应的 API</li></ul>',26)])])}const p=a(n,[["render",s]]);export{u as __pageData,p as default};
